/** Sprite for an appliance type, or null for types without bespoke art. */
export function spriteKeyForType(type: string): VehicleSpriteKey | null {
  switch (type) {
    case "WrL":
    case "WrT":
    case "L6P":
      return "pump";
    case "TL":
    case "HLP":
      return "alp";
    case "TRU_pump":
      return "tru";
    case "TRU_van":
      return "truvan";
    case "PM":
      return "pm";
    case "HLL":
      return "hll";
    case "SDU":
      return "decon";
    case "Police_Response":
    case "Police_Dog":
      return "pol_estate";
    case "Police_RPU":
      return "pol_rpu";
    case "Police_ARV":
      return "pol_arv";
    case "Police_SIO":
      return "pol_unm_saloon";
    case "Police_Search":
      return "pol_unm";
    default:
      return null;
  }
}
